'use strict';

/**
 * Summarize active quantity rows by normalized category.
 *
 * @param {Array<{category: string, quantity: number, active: boolean}>} rows
 * @returns {Array<{category: string, quantity: number}>}
 */
function summarize(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }

  const totals = new Map();

  for (const row of rows) {
    if (row === null || typeof row !== 'object') {
      throw new TypeError('row must be an object');
    }
    if (typeof row.category !== 'string') {
      throw new TypeError('row.category must be a string');
    }
    const category = row.category.trim().toLowerCase();
    if (category.length === 0) {
      throw new TypeError('row.category must not be blank');
    }
    if (!Number.isInteger(row.quantity) || row.quantity < 0) {
      throw new TypeError('row.quantity must be a nonnegative integer');
    }
    if (typeof row.active !== 'boolean') {
      throw new TypeError('row.active must be boolean');
    }

    if (row.active) {
      totals.set(category, (totals.get(category) ?? 0) + row.quantity);
    }
  }

  return Array.from(totals, ([category, quantity]) => ({ category, quantity }))
    .sort((left, right) => (left.category < right.category ? -1 : left.category > right.category ? 1 : 0));
}

module.exports = { summarize };

