const rows = [{category:' Z ',quantity:0,active:true},{category:'a',quantity:4,active:true},
 {category:'A ',quantity:7,active:true},{category:'z',quantity:99,active:false},
 {category:'__proto__',quantity:2,active:true}];
const before = JSON.stringify(rows);
assert.deepEqual(summarize(rows),[{category:'__proto__',quantity:2},{category:'a',quantity:11},{category:'z',quantity:0}]);
assert.equal(JSON.stringify(rows),before);
assert.deepEqual(summarize([]),[]);
assert.deepEqual(summarize([{category:'x',quantity:99,active:false}]),[]);
for (const invalid of [null,{},'x',42,[null],[{}],[{category:5,quantity:1,active:true}],
 [{category:' ',quantity:0,active:false}],[{category:'a',quantity:-1,active:false}],
 [{category:'a',quantity:0.1,active:true}],[{category:'a',quantity:NaN,active:true}],
 [{category:'a',quantity:Infinity,active:true}],[{category:'a',quantity:1,active:'true'}]]) {
 assert.throws(()=>summarize(invalid),TypeError);
}
// This oracle must also reject a structurally plausible but wrong result.
assert.throws(()=>assert.deepEqual([],summarize(rows)));
